(2280314, 314673, 4008, '<td valign="top">I think the rocks could do with some more contrast, they are rather dark and flat now. Nice framing with the branch.</td>', 'I think the rocks could do with some more contrast, they are rather dark and flat now. Nice framing with the branch.', '2006-04-02 12:06:50.000000', NULL, 1),
(2280316, 314795, 35078, '<td valign="top">Good motion blur. I had a similar concept and got hammered with my lowest score ever. Hope you do well with this shot.</td>', 'Good motion blur. I had a similar concept and got hammered with my lowest score ever. Hope you do well with this shot.', '2006-04-02 12:06:54.000000', NULL, 1),
(2280319, 314633, 4008, '<td valign="top">nice light, but a bit too much glow effect for my taste. Taking a lower camera standpoint would have emphasised the small boy against the big pier and waves.</td>', 'nice light, but a bit too much glow effect for my taste. Taking a lower camera standpoint would have emphasised the small boy against the big pier and waves.', '2006-04-02 12:09:06.000000', NULL, 1),
(2280321, 314613, 4008, '<td valign="top">beautiful image with lots of atmosphere. Nice framing.</td>', 'beautiful image with lots of atmosphere. Nice framing.', '2006-04-02 12:10:54.000000', NULL, 1),
(2280327, 314933, 3032, '<td valign="top">I like the dark wintery mood with good control of the highlights here.</td>', 'I like the dark wintery mood with good control of the highlights here.', '2006-04-02 12:13:18.000000', NULL, 1),
(2280330, 314479, 3032, '<td valign="top">Cool concept/compo and works well in B&amp;W. The person would stand out better if he had been seated one seat to the back or to the right. Now he blends in too much with the structure in the background.</td>', 'Cool concept/compo and works well in B&W. The person would stand out better if he had been seated one seat to the back or to the right. Now he blends in too much with the structure in the background.', '2006-04-02 12:15:00.000000', NULL, 1),
(2280335, 315037, 3032, '<td valign="top">Nice dark mood fits the scene. I like it how the Spanish grass on the trees gives a sence of location. I''d guess its in the old South of the US. Would not at all be surprised (given the subject and style) that this is Sher''s work.</td>', 'Nice dark mood fits the scene. I like it how the Spanish grass on the trees gives a sence of location. I''d guess its in the old South of the US. Would not at all be surprised (given the subject and style) that this is Sher''s work.', '2006-04-02 12:17:37.000000', NULL, 1),
(2280337, 314669, 3032, '<td valign="top">The way of processing adds a lot of depth to the scene. Nice work.</td>', 'The way of processing adds a lot of depth to the scene. Nice work.', '2006-04-02 12:18:14.000000', NULL, 1),
(2280338, 315029, 3032, '<td valign="top">Faces look a bit plasticky (noise reduction?). I like it how the lines of the roof lead the eye trough the scene.</td>', 'Faces look a bit plasticky (noise reduction?). I like it how the lines of the roof lead the eye trough the scene.', '2006-04-02 12:19:37.000000', NULL, 1),
(2280342, 314864, 3032, '<td valign="top">Great colors, lovely sky.</td>', 'Great colors, lovely sky.', '2006-04-02 12:20:33.000000', NULL, 1),
(2280350, 314820, 3032, '<td valign="top">I don''t like the border much and it''s unfortunate that the door is a bit in the centre. The right side doesn''t add much to the photo. Processing is interesting but could possibly benefit from more contrast.</td>', 'I don''t like the border much and it''s unfortunate that the door is a bit in the centre. The right side doesn''t add much to the photo. Processing is interesting but could possibly benefit from more contrast.', '2006-04-02 12:22:02.000000', NULL, 1),
(2280352, 314648, 3032, '<td valign="top">Nice colors and composition, the diagonal along the top of the plants and the position of the reed cigars makes it work.</td>', 'Nice colors and composition, the diagonal along the top of the plants and the position of the reed cigars makes it work.', '2006-04-02 12:22:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2280357, 315049, 3032, '<td valign="top">Nice compo. Would look better in late afternoon sunlight I think, but you cannot have it all. :)</td>', 'Nice compo. Would look better in late afternoon sunlight I think, but you cannot have it all. :)', '2006-04-02 12:25:31.000000', NULL, 1),
(2280358, 314431, 4008, '<td valign="top">great atmosphere.</td>', 'great atmosphere.', '2006-04-02 12:26:22.000000', NULL, 1),
(2280359, 314662, 3032, '<td valign="top">Good use of the lamp post. Scenes like this are always so interesting but when you photograph them they look dull. Using an element like this helps.</td>', 'Good use of the lamp post. Scenes like this are always so interesting but when you photograph them they look dull. Using an element like this helps.', '2006-04-02 12:28:15.000000', NULL, 1),
(2280360, 314437, 3032, '<td valign="top">Great view and photo. The water on the beach adds that little bit of extra to an already good scene.</td>', 'Great view and photo. The water on the beach adds that little bit of extra to an already good scene.', '2006-04-02 12:29:13.000000', NULL, 1),
(2280365, 314441, 3032, '<td valign="top">It''s always worth it to go outdoors with your camera in a storm. :)</td>', 'It''s always worth it to go outdoors with your camera in a storm. :)', '2006-04-02 12:30:25.000000', NULL, 1),
(2280373, 314833, 4008, '<td valign="top">very underexposed</td>', 'very underexposed', '2006-04-02 12:33:43.000000', NULL, 1),
(2280374, 314642, 5286, '<td valign="top">Cute! I think a little more processing to bring out a full tonal range would definitely make this pop!</td>', 'Cute! I think a little more processing to bring out a full tonal range would definitely make this pop!', '2006-04-02 12:35:15.000000', NULL, 1),
(2280375, 314795, 5286, '<td valign="top">Woohoo I wouldn''t have dreamt of that in 2002 :)</td>', 'Woohoo I wouldn''t have dreamt of that in 2002 :)', '2006-04-02 12:35:45.000000', NULL, 1),
(2280377, 314426, 3032, '<td valign="top">Good idea, good pose, she has a hot daring sexy look on her face.<br/>Don''t like the background in the right section behind her and the hotspots on her suit are a bit harsh. Should be good for a ribbon, I hope you finally fetch the blue one with this.</td>', 'Good idea, good pose, she has a hot daring sexy look on her face.Don''t like the background in the right section behind her and the hotspots on her suit are a bit harsh. Should be good for a ribbon, I hope you finally fetch the blue one with this.', '2006-04-02 12:36:18.000000', NULL, 1),
(2280381, 314929, 3032, '<td valign="top">Sweet colors. Gives a spring feeling while it was shot in the autumn I guess. :)</td>', 'Sweet colors. Gives a spring feeling while it was shot in the autumn I guess. :)', '2006-04-02 12:38:14.000000', NULL, 1),
(2280382, 314477, 4008, '<td valign="top">great expression, like he feels silly with the baseball cap and is worried about what comes next. Any more humiliation .....</td>', 'great expression, like he feels silly with the baseball cap and is worried about what comes next. Any more humiliation .....', '2006-04-02 12:38:44.000000', NULL, 1),
(2280385, 314489, 3032, '<td valign="top">Good b&amp;w. The lady on the left doesn''t add much, a portrait-crop study of the one on the right would be better imho, at least that''s where my attention goes to all the time.</td>', 'Good b&w. The lady on the left doesn''t add much, a portrait-crop study of the one on the right would be better imho, at least that''s where my attention goes to all the time.', '2006-04-02 12:39:53.000000', NULL, 1),
(2280386, 314448, 4008, '<td valign="top">best sunset in the challenge, great composition.</td>', 'best sunset in the challenge, great composition.', '2006-04-02 12:40:07.000000', NULL, 1),
(2280390, 314663, 3032, '<td valign="top">Despite the softness still good because of the content. Would perhaps have been better if the guy would have been a little bit further away from the wall.</td>', 'Despite the softness still good because of the content. Would perhaps have been better if the guy would have been a little bit further away from the wall.', '2006-04-02 12:41:37.000000', NULL, 1),
(2280393, 314484, 3032, '<td valign="top">Nice, very nice.</td>', 'Nice, very nice.', '2006-04-02 12:43:01.000000', NULL, 1),
(2280397, 314600, 3032, '<td valign="top">Good lighting and posing. I like it that you choose to show it in b&amp;w.</td>', 'Good lighting and posing. I like it that you choose to show it in b&w.', '2006-04-02 12:45:26.000000', NULL, 1),
(2280399, 314476, 3032, '<td valign="top">Cool subject to distort with a fisheye. Makes you feel like you are inside a snail''s shell.</td>', 'Cool subject to distort with a fisheye. Makes you feel like you are inside a snail''s shell.', '2006-04-02 12:47:11.000000', NULL, 1),
(2280401, 314497, 3032, '<td valign="top">Great, love it. The way the light works makes this so dynamic. Very cool b&amp;w.</td>', 'Great, love it. The way the light works makes this so dynamic. Very cool b&w.', '2006-04-02 12:48:48.000000', NULL, 1),
(2280405, 314412, 3032, '<td valign="top">Good eye to shoot it as this angle, makes it very interesting to view.</td>', 'Good eye to shoot it as this angle, makes it very interesting to view.', '2006-04-02 12:50:06.000000', NULL, 1),
(2280415, 314934, 52713, '<td valign="top">Nice composistion.</td>', 'Nice composistion.', '2006-04-02 13:02:14.000000', NULL, 1),
(2280416, 315053, 42013, '<td valign="top">I would like the image better without the dead tree.</td>', 'I would like the image better without the dead tree.', '2006-04-02 13:03:22.000000', NULL, 1),
(2280419, 314486, 52713, '<td valign="top">Love the "God lighting"! Recommend that you burn down the foreground highlights a bit</td>', 'Love the "God lighting"! Recommend that you burn down the foreground highlights a bit', '2006-04-02 13:03:59.000000', NULL, 1),
(2280420, 314973, 52713, '<td valign="top">Classic "S" composisiton with real nice side lighting. Ball element adds a great visual contrast.</td>', 'Classic "S" composisiton with real nice side lighting. Ball element adds a great visual contrast.', '2006-04-02 13:05:52.000000', NULL, 1),
