(2280426, 314628, 52713, '<td valign="top">Love the back lighting and the angle.</td>', 'Love the back lighting and the angle.', '2006-04-02 13:09:31.000000', NULL, 1),
(2280431, 314568, 52713, '<td valign="top">Cute kitten</td>', 'Cute kitten', '2006-04-02 13:12:31.000000', NULL, 1),
(2280432, 314662, 52713, '<td valign="top">nice contrast of warmth and cold. Nice moment</td>', 'nice contrast of warmth and cold. Nice moment', '2006-04-02 13:13:21.000000', NULL, 1),
(2280450, 314530, 3032, '<td valign="top">Cool composition with that plant in front, frames the person well and the strong diagonal helps to lead the eye along the frame. With only the background it would have been boring.</td>', 'Cool composition with that plant in front, frames the person well and the strong diagonal helps to lead the eye along the frame. With only the background it would have been boring.', '2006-04-02 13:31:23.000000', NULL, 1),
(2280451, 314431, 3032, '<td valign="top">Nice colors and good use of the natural lines.</td>', 'Nice colors and good use of the natural lines.', '2006-04-02 13:32:15.000000', NULL, 1),
(2280460, 314833, 3032, '<td valign="top">Maybe it was intentional, but I do not like the dark tone.</td>', 'Maybe it was intentional, but I do not like the dark tone.', '2006-04-02 13:38:50.000000', NULL, 1),
