(2298126, 314829, 48968, '<td valign="top">I really like this shot! There is something about the sky on the left-hand side of the frame that doesn''t sit right with me, but it doesn''t take away from my enjoyment of the image!</td>', 'I really like this shot! There is something about the sky on the left-hand side of the frame that doesn''t sit right with me, but it doesn''t take away from my enjoyment of the image!', '2006-04-08 19:23:33.000000', NULL, 1),
(2298128, 314680, 48968, '<td valign="top">There is such sadness in the eyes of that Tiger. I guess being stuck behind chainlink fences everyday will do that...at least that''s what the image ''says'' to me. :)</td>', 'There is such sadness in the eyes of that Tiger. I guess being stuck behind chainlink fences everyday will do that...at least that''s what the image ''says'' to me. :)', '2006-04-08 19:25:46.000000', NULL, 1),
