INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2299443, 314831, 14986, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Pug-H:</b></div><hr/><i> I wonder what part of the canyon that is. </i></td></tr></table> <br/> <br/>It was one of the main overlooks, off to the side a bit.  Seems to me like it wasn''t too far from the lodge area.  We were on a bus tour of the canyon with stops at the regular sites.   I don''t know that much about the canyon to tell you which rim it was or anything like that.  It was early in April, so I think the rim that is closed for the winter may not have even been open yet.   Sorry I can''t be more specific!</td>', 'Originally posted by Pug-H: I wonder what part of the canyon that is.   It was one of the main overlooks, off to the side a bit.  Seems to me like it wasn''t too far from the lodge area.  We were on a bus tour of the canyon with stops at the regular sites.   I don''t know that much about the canyon to tell you which rim it was or anything like that.  It was early in April, so I think the rim that is closed for the winter may not have even been open yet.   Sorry I can''t be more specific!', '2006-04-09 14:54:17.000000', NULL, 0),
(2299475, 314758, 37893, '<td valign="top">Amazing photo as a result of an outstanding post processing. Great job Arni! You`re definitely right behind jjbeguin for the most ribbons!</td>', 'Amazing photo as a result of an outstanding post processing. Great job Arni! You`re definitely right behind jjbeguin for the most ribbons!', '2006-04-09 15:27:29.000000', NULL, 0),
